    {
        

        companion object
    }
    
    /**
     * From the uri pathname.
     *
     * - `segment_index`: 0-based over non-empty path segments (default: 0).
     * e.g. `app://_/my-app/index.html` with index 0 -> bundle `my-app`.
     */
