            17 -> WebviewBundleException.CoreSerdeJson(FfiConverterString.read(buf))
            18 -> WebviewBundleException.CoreCannotResolveProxyServer(FfiConverterString.read(buf))
            19 -> WebviewBundleException.CoreHttpClient(FfiConverterString.read(buf))
            20 -> WebviewBundleException.CoreRemoteHttp(FfiConverterString.read(buf))
            21 -> WebviewBundleException.CoreBadRemoteResponse(FfiConverterString.read(buf))
            22 -> WebviewBundleException.CoreInvalidRemoteConfig(FfiConverterString.read(buf))
            23 -> WebviewBundleException.CoreInvalidUpdaterConfig(FfiConverterString.read(buf))
            24 -> WebviewBundleException.CoreInvalidIntegrity(FfiConverterString.read(buf))
            25 -> WebviewBundleException.CoreIntegrityRequired(FfiConverterString.read(buf))
            26 -> WebviewBundleException.CoreIntegrityVerifyFailed(FfiConverterString.read(buf))
            27 -> WebviewBundleException.CoreInvalidSignature(FfiConverterString.read(buf))
            28 -> WebviewBundleException.CoreInvalidSignatureKey(FfiConverterString.read(buf))
            29 -> WebviewBundleException.CoreExpectSignatureNotFound(FfiConverterString.read(buf))
            30 -> WebviewBundleException.CoreSignatureVerifyFailed(FfiConverterString.read(buf))
            31 -> WebviewBundleException.CoreGeneric(FfiConverterString.read(buf))
            32 -> WebviewBundleException.BindingInvalidHeaderName(FfiConverterString.read(buf))
            33 -> WebviewBundleException.BindingInvalidHeaderValue(FfiConverterString.read(buf))
            34 -> WebviewBundleException.BindingInvalidSignatureOptions(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: WebviewBundleException): ULong {
        return 4UL
    }

    override fun write(value: WebviewBundleException, buf: ByteBuffer) {
        when(value) {
            is WebviewBundleException.CoreIo -> {
                buf.putInt(1)
                Unit
            }
            is WebviewBundleException.CoreCompress -> {
                buf.putInt(2)
                Unit
            }
            is WebviewBundleException.CoreDecompress -> {
                buf.putInt(3)
                Unit
            }
            is WebviewBundleException.CoreEncode -> {
                buf.putInt(4)
                Unit
            }
            is WebviewBundleException.CoreDecode -> {
                buf.putInt(5)
                Unit
            }
            is WebviewBundleException.CoreHttp -> {
                buf.putInt(6)
                Unit
            }
            is WebviewBundleException.CoreHttpInvalidUri -> {
                buf.putInt(7)
                Unit
            }
            is WebviewBundleException.CoreCancelled -> {
                buf.putInt(8)
                Unit
            }
            is WebviewBundleException.CoreTimeout -> {
                buf.putInt(9)
                Unit
            }
            is WebviewBundleException.CoreInvalidMagicNum -> {
                buf.putInt(10)
                Unit
            }
            is WebviewBundleException.CoreInvalidVersion -> {
                buf.putInt(11)
                Unit
            }
            is WebviewBundleException.CoreInvalidHeaderChecksum -> {
                buf.putInt(12)
                Unit
            }
            is WebviewBundleException.CoreInvalidIndexChecksum -> {
                buf.putInt(13)
                Unit
            }
            is WebviewBundleException.CoreChecksumMismatch -> {
                buf.putInt(14)
                Unit
            }
            is WebviewBundleException.CoreBundleNotFound -> {
                buf.putInt(15)
                Unit
            }
            is WebviewBundleException.CoreInvalidFilepath -> {
                buf.putInt(16)
                Unit
            }
            is WebviewBundleException.CoreSerdeJson -> {
                buf.putInt(17)
                Unit
            }
            is WebviewBundleException.CoreCannotResolveProxyServer -> {
                buf.putInt(18)
                Unit
            }
            is WebviewBundleException.CoreHttpClient -> {
                buf.putInt(19)
                Unit
            }
            is WebviewBundleException.CoreRemoteHttp -> {
                buf.putInt(20)
                Unit
            }
            is WebviewBundleException.CoreBadRemoteResponse -> {
                buf.putInt(21)
                Unit
            }
            is WebviewBundleException.CoreInvalidRemoteConfig -> {
                buf.putInt(22)
                Unit
            }
            is WebviewBundleException.CoreInvalidUpdaterConfig -> {
                buf.putInt(23)
                Unit
            }
            is WebviewBundleException.CoreInvalidIntegrity -> {
                buf.putInt(24)
                Unit
            }
            is WebviewBundleException.CoreIntegrityRequired -> {
                buf.putInt(25)
                Unit
            }
            is WebviewBundleException.CoreIntegrityVerifyFailed -> {
                buf.putInt(26)
                Unit
            }
            is WebviewBundleException.CoreInvalidSignature -> {
                buf.putInt(27)
                Unit
            }
            is WebviewBundleException.CoreInvalidSignatureKey -> {
                buf.putInt(28)
                Unit
            }
            is WebviewBundleException.CoreExpectSignatureNotFound -> {
                buf.putInt(29)
                Unit
            }
            is WebviewBundleException.CoreSignatureVerifyFailed -> {
                buf.putInt(30)
                Unit
            }
            is WebviewBundleException.CoreGeneric -> {
                buf.putInt(31)
                Unit
            }
            is WebviewBundleException.BindingInvalidHeaderName -> {
                buf.putInt(32)
                Unit
            }
            is WebviewBundleException.BindingInvalidHeaderValue -> {
                buf.putInt(33)
                Unit
            }
            is WebviewBundleException.BindingInvalidSignatureOptions -> {
                buf.putInt(34)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




